 1→// TypeScript types for structured editor form
 2→
 3→export type RelationOperator =
 4→    | '='
 5→    | '!='
 6→    | '>'
 7→    | '>='
 8→    | '<'
 9→    | '<='
10→    | 'within'
11→    | 'not_in_last'
12→    | 'contains'
13→    | 'not_contains';
14→
15→export type RelationCategory = 'standard' | 'range' | 'temporal';
16→
17→export type TemporalUnit = 'days' | 'weeks' | 'months' | 'years';
18→
19→export interface StandardValue {
20→    type: 'standard';
21→    value: string;
22→    unit: string;
23→}
24→
25→export interface RangeValue {
26→    type: 'range';
27→    min: string;
28→    max: string;
29→    unit: string;
30→}
31→
32→export interface TemporalValue {
33→    type: 'temporal';
34→    duration: string;
35→    unit: TemporalUnit;
36→}
37→
38→export type FieldValue = StandardValue | RangeValue | TemporalValue;
39→
40→// Single field mapping with all possible fields
41→export interface FieldMapping {
42→    entity: string;
43→    entity_code?: string;
44→    entity_system?: string;
45→    omop_concept_id?: string;
46→    relation: RelationOperator | '';
47→    value: FieldValue;
48→}
49→
50→// Form values now contain an array of mappings
51→export interface StructuredFieldFormValues {
52→    mappings: FieldMapping[];
53→}
54→
55→export interface StructuredFieldEditorProps {
56→    criterionId: string;
57→    initialValues?: Partial<StructuredFieldFormValues>;
58→    onSave: (values: StructuredFieldFormValues) => void;
59→    onCancel: () => void;
60→    isSubmitting?: boolean;
61→}
