54→export function useCriteriaSpreadsheet(filters: CriteriaFilters) {
55→    const params = new URLSearchParams({
56→        page: String(filters.page),
57→        page_size: String(filters.pageSize),
58→    });
59→
60→    if (filters.criteriaType) params.set('criteria_type', filters.criteriaType);
61→    if (filters.category) params.set('category', filters.category);
62→    if (filters.protocolId) params.set('protocol_id', filters.protocolId);
63→    if (filters.minConfidence !== undefined)
64→        params.set('min_confidence', String(filters.minConfidence));
65→    if (filters.sortBy) params.set('sort_by', filters.sortBy);
66→    if (filters.sortOrder) params.set('sort_order', filters.sortOrder);
67→    if (filters.hasGrounding !== undefined)
68→        params.set('has_grounding', String(filters.hasGrounding));
69→
70→    return useQuery({
71→        queryKey: ['criteria-structured', filters],
72→        queryFn: () =>
73→            fetchApi<StructuredCriteriaResponse>(`/criteria/structured?${params.toString()}`),
74→        staleTime: 30_000,
75→    });
76→}
