126→                        'w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background',
127→                        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
128→                        'disabled:opacity-50 disabled:cursor-not-allowed'
129→                    )}
130→                />
131→            </label>
132→            <label className="block">
133→                <span className="block text-sm font-medium text-muted-foreground mb-1">Unit</span>
134→                <input
135→                    type="text"
136→                    placeholder="e.g., mg/dL"
137→                    value={rangeValue.unit}
138→                    onChange={(e) =>
139→                        onChange({
140→                            type: 'range',
141→                            min: rangeValue.min,
142→                            max: rangeValue.max,
143→                            unit: e.target.value,
144→                        })
145→                    }
146→                    disabled={disabled}
147→                    className={cn(
148→                        'w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background',
149→                        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
150→                        'disabled:opacity-50 disabled:cursor-not-allowed'
151→                    )}
152→                />
153→            </label>
154→        </div>
155→    );
156→}
157→
158→// Sub-component for temporal duration + unit dropdown
159→function TemporalValueInput({
160→    value,
161→    onChange,
162→    disabled,
163→}: {
164→    value: FieldValue;
165→    onChange: (value: FieldValue) => void;
166→    disabled?: boolean;
167→}) {
168→    const temporalValue =
169→        value.type === 'temporal' ? value : { duration: '', unit: 'days' as const };
170→    const selectedUnit = TEMPORAL_UNITS.find((u) => u.value === temporalValue.unit);
171→
172→    return (
173→        <div className="grid grid-cols-2 gap-3">
174→            <label className="block">
175→                <span className="block text-sm font-medium text-muted-foreground mb-1">
176→                    Duration
177→                </span>
178→                <input
179→                    type="text"
180→                    value={temporalValue.duration}
181→                    onChange={(e) =>
182→                        onChange({
183→                            type: 'temporal',
184→                            duration: e.target.value,
185→                            unit: temporalValue.unit,
186→                        })
187→                    }
188→                    disabled={disabled}
189→                    className={cn(
190→                        'w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background',
191→                        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
192→                        'disabled:opacity-50 disabled:cursor-not-allowed'
193→                    )}
194→                />
195→            </label>
196→            <div>
197→                <span className="block text-sm font-medium text-muted-foreground mb-1">Unit</span>
198→                <Select.Root
199→                    value={temporalValue.unit}
200→                    onValueChange={(newUnit) =>
201→                        onChange({
202→                            type: 'temporal',
203→                            duration: temporalValue.duration,
204→                            unit: newUnit as 'days' | 'weeks' | 'months' | 'years',
205→                        })
206→                    }
207→                    disabled={disabled}
208→                >
209→                    <Select.Trigger
210→                        className={cn(
211→                            'w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background',
212→                            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
213→                            'flex items-center justify-between',
214→                            'disabled:opacity-50 disabled:cursor-not-allowed'
215→                        )}
216→                    >
217→                        <Select.Value>{selectedUnit?.label ?? 'Select unit'}</Select.Value>
218→                        <Select.Icon>
219→                            <ChevronDown className="h-4 w-4 opacity-50" />
220→                        </Select.Icon>
221→                    </Select.Trigger>
222→
223→                    <Select.Portal>
224→                        <Select.Content
225→                            className="overflow-hidden bg-popover rounded-md border shadow-md z-50"
226→                            position="popper"
227→                            sideOffset={4}
228→                        >
229→                            <Select.Viewport className="p-1">
230→                                {TEMPORAL_UNITS.map((unit) => (
231→                                    <Select.Item
232→                                        key={unit.value}
233→                                        value={unit.value}
234→                                        className={cn(
235→                                            'relative flex cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none',
236→                                            'focus:bg-accent focus:text-accent-foreground',
237→                                            'data-[disabled]:pointer-events-none data-[disabled]:opacity-50'
238→                                        )}
239→                                    >
240→                                        <Select.ItemText>{unit.label}</Select.ItemText>
241→                                    </Select.Item>
242→                                ))}
243→                            </Select.Viewport>
244→                        </Select.Content>
245→                    </Select.Portal>
246→                </Select.Root>
247→            </div>
248→        </div>
249→    );
250→}
251→
252→// Main adaptive value input component
253→export function ValueInput({ category, value, onChange, disabled }: ValueInputProps) {
254→    switch (category) {
255→        case 'standard':
256→            return <StandardValueInput value={value} onChange={onChange} disabled={disabled} />;
257→        case 'range':
258→            return <RangeValueInput value={value} onChange={onChange} disabled={disabled} />;
259→        case 'temporal':
260→            return <TemporalValueInput value={value} onChange={onChange} disabled={disabled} />;
261→    }
262→}
